.lifecycle-period span, .lifecycle-period strong, .lifecycle-period small { display: block; }.lifecycle-period span { color: var(--ink-faint); font-size: .62rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }.lifecycle-period strong { margin-top: .25rem; font-size: .88rem; }.lifecycle-period small { margin-top: .1rem; color: var(--ink-soft); font-size: .7rem; }
