.lifecycle-workspace { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(280px, .75fr); gap: 1rem; align-items: start; }.lifecycle-form, .lifecycle-guide, .lifecycle-history { padding: 1.25rem; }.lifecycle-section-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; margin-bottom: 1.1rem; }.lifecycle-section-heading h2, .lifecycle-history-heading h2 { margin: .25rem 0 .25rem; color: var(--ink); font-size: 1.05rem; font-weight: 800; letter-spacing: -.02em; }.lifecycle-section-heading p:not(.lifecycle-kicker), .lifecycle-history-heading p:not(.lifecycle-kicker) { margin: 0; color: var(--ink-faint); font-size: .72rem; }.lifecycle-form-status, .lifecycle-history-count { display: inline-flex; align-items: center; min-height: 25px; padding: .25rem .55rem; color: var(--green); background: var(--green-soft); border-radius: 999px; font-size: .62rem; font-weight: 800; white-space: nowrap; }
.lifecycle-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .85rem; }.lifecycle-field { display: grid; gap: .35rem; min-width: 0; color: var(--ink-soft); font-size: .72rem; font-weight: 750; }.lifecycle-field-wide { grid-column: 1 / -1; }.lifecycle-field b { color: var(--red); }.lifecycle-field em { color: var(--ink-faint); font-size: .65rem; font-style: normal; font-weight: 500; }.lifecycle-field input, .lifecycle-field select, .lifecycle-field textarea, .lifecycle-history-toolbar select { width: 100%; min-height: 40px; padding: .62rem .72rem; color: var(--ink); background: var(--surface); border: 1px solid var(--line-strong); border-radius: .65rem; outline: 0; font-size: .78rem; font-weight: 500; transition: border-color .16s ease, box-shadow .16s ease; }.lifecycle-field textarea { min-height: 84px; resize: vertical; }.lifecycle-field input:focus, .lifecycle-field select:focus, .lifecycle-field textarea:focus, .lifecycle-history-toolbar select:focus { border-color: var(--primary); box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 18%, transparent); }.lifecycle-field select:disabled { cursor: not-allowed; opacity: .58; }.lifecycle-hint { color: var(--ink-faint); font-size: .62rem; font-weight: 500; text-align: right; }.lifecycle-error { margin: 0; color: var(--red); font-size: .7rem; font-weight: 650; }
