.lifecycle-guide { background: var(--surface-subtle); }.lifecycle-guide-list { display: grid; gap: 1rem; }.lifecycle-guide-list article { display: grid; grid-template-columns: 30px 1fr; gap: .7rem; align-items: start; }.lifecycle-guide-number { display: grid; width: 28px; height: 28px; place-items: center; color: var(--primary); background: var(--primary-soft); border-radius: .55rem; font-size: .62rem; font-weight: 850; }.lifecycle-guide-list strong { color: var(--ink); font-size: .75rem; }.lifecycle-guide-list p { margin: .2rem 0 0; color: var(--ink-faint); font-size: .68rem; line-height: 1.55; }.lifecycle-warning { display: flex; align-items: flex-start; gap: .55rem; margin-top: 1.25rem; padding: .7rem; color: var(--gold); background: var(--gold-soft); border: 1px solid color-mix(in srgb, var(--gold) 22%, var(--line)); border-radius: .65rem; font-size: .66rem; line-height: 1.5; }.lifecycle-warning svg { width: 15px; height: 15px; flex: 0 0 auto; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.8; }
.lifecycle-history { padding: 0; overflow: hidden; }.lifecycle-history-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; padding: 1.25rem 1.3rem 1rem; }.lifecycle-history-toolbar { display: flex; gap: .65rem; padding: 0 1.3rem 1rem; border-bottom: 1px solid var(--line); }.lifecycle-history-toolbar select { width: 180px; min-height: 38px; }.lifecycle-search { display: flex; align-items: center; gap: .45rem; flex: 1; min-height: 38px; padding: 0 .7rem; color: var(--ink-faint); background: var(--surface-subtle); border: 1px solid var(--line); border-radius: .65rem; }.lifecycle-search svg { width: 16px; height: 16px; flex: 0 0 auto; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.8; }.lifecycle-search input { width: 100%; color: var(--ink); background: transparent; border: 0; outline: 0; font-size: .76rem; }.lifecycle-search input::placeholder { color: var(--ink-faint); }
.lifecycle-table-wrap { overflow-x: auto; }.lifecycle-table { width: 100%; min-width: 780px; border-collapse: collapse; color: var(--ink-soft); font-size: .74rem; }.lifecycle-table th { padding: .75rem 1.1rem; color: var(--ink-faint); background: var(--surface-subtle); border-bottom: 1px solid var(--line); font-size: .63rem; font-weight: 850; letter-spacing: .06em; text-align: left; text-transform: uppercase; white-space: nowrap; }.lifecycle-table td { padding: .85rem 1.1rem; border-bottom: 1px solid var(--line); vertical-align: middle; }.lifecycle-table tbody tr { transition: background-color .16s ease; }.lifecycle-table tbody tr:hover { background: color-mix(in srgb, var(--primary-soft) 42%, var(--surface)); }.lifecycle-table td strong, .lifecycle-table td small { display: block; }.lifecycle-table td strong { color: var(--ink); font-size: .76rem; }.lifecycle-table td small { margin-top: .15rem; color: var(--ink-faint); font-size: .64rem; }.lifecycle-date { color: var(--ink-soft); white-space: nowrap; }.lifecycle-action-badge { display: inline-flex; align-items: center; padding: .28rem .55rem; border-radius: 999px; font-size: .63rem; font-weight: 800; white-space: nowrap; }.lifecycle-action-promoted { color: var(--primary); background: var(--primary-soft); }.lifecycle-action-retained { color: var(--gold); background: var(--gold-soft); }.lifecycle-action-graduated { color: var(--green); background: var(--green-soft); }.lifecycle-action-withdrawn { color: var(--red); background: var(--red-soft); }.lifecycle-transfer { display: flex; align-items: center; gap: .45rem; color: var(--ink-soft); white-space: nowrap; }.lifecycle-transfer svg { width: 14px; height: 14px; flex: 0 0 auto; fill: none; stroke: var(--ink-faint); stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.8; }.lifecycle-note { max-width: 240px; overflow: hidden; color: var(--ink-faint); text-overflow: ellipsis; white-space: nowrap; }.lifecycle-empty { padding: 3rem 1rem !important; color: var(--ink-faint); text-align: center; }
@media (max-width: 900px) { .lifecycle-workspace { grid-template-columns: 1fr; } .lifecycle-guide { order: -1; } }
@media (max-width: 640px) { .lifecycle-hero { align-items: stretch; flex-direction: column; padding: 1.2rem; }.lifecycle-period { min-width: 0; }.lifecycle-stats { grid-template-columns: 1fr; gap: .65rem; }.lifecycle-fields { grid-template-columns: 1fr; }.lifecycle-field-wide { grid-column: auto; }.lifecycle-form, .lifecycle-guide { padding: 1rem; }.lifecycle-form-footer, .lifecycle-history-toolbar { align-items: stretch; flex-direction: column; }.lifecycle-submit, .lifecycle-history-toolbar select { width: 100%; }.lifecycle-history-heading { padding: 1rem; }.lifecycle-history-toolbar { padding: 0 1rem 1rem; } }
